/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { StringManager } from "../../src/i18n/StringManager.js";
import { InstrumentsScreen } from "../../src/instruments/InstrumentsScreen.js";
import { PhaseScreen } from "../../src/phase-relationships/PhaseScreen.js";
import { StandingWavesPreferencesModel } from "../../src/preferences/StandingWavesPreferencesModel.js";
import { ReflectionScreen } from "../../src/reflection/ReflectionScreen.js";
import StandingWavesColors from "../../src/StandingWavesColors.js";
import { StandingWavesScreen } from "../../src/standing-waves/StandingWavesScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from standingWavesQueryParameters.
  const simPreferences = new StandingWavesPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new ReflectionScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().reflectionStringProperty,
      tandem: Tandem.ROOT.createTandem("reflectionScreen"),
      backgroundColorProperty: StandingWavesColors.backgroundColorProperty,
    }),
    new PhaseScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().phaseRelationshipsStringProperty,
      tandem: Tandem.ROOT.createTandem("phaseRelationshipsScreen"),
      backgroundColorProperty: StandingWavesColors.backgroundColorProperty,
    }),
    new StandingWavesScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().standingWavesStringProperty,
      tandem: Tandem.ROOT.createTandem("standingWavesScreen"),
      backgroundColorProperty: StandingWavesColors.backgroundColorProperty,
    }),
    new InstrumentsScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().instrumentsStringProperty,
      tandem: Tandem.ROOT.createTandem("instrumentsScreen"),
      backgroundColorProperty: StandingWavesColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { StandingWavesColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
